private void handleExit(){
  SharedPreferences prefs=PreferenceManager.getDefaultSharedPreferences(getContext());
  boolean auto_undecrypt=prefs.getBoolean("auto_undecrypt",false);
  if (auto_undecrypt && viewType == AdapterMessage.ViewType.THREAD) {
    List<Long> ids=new ArrayList<>();
    for (int i=0; i < adapter.getItemCount(); i++) {
      TupleMessageEx message=adapter.getItemAtPosition(i);
      if (message == null)       continue;
      if ((EntityMessage.PGP_SIGNENCRYPT.equals(message.ui_encrypt) && !EntityMessage.PGP_SIGNENCRYPT.equals(message.encrypt)) || (EntityMessage.SMIME_SIGNENCRYPT.equals(message.ui_encrypt) && !EntityMessage.SMIME_SIGNENCRYPT.equals(message.encrypt)))       ids.add(message.id);
    }
    Bundle args=new Bundle();
    args.putLongArray("ids",Helper.toLongArray(ids));
    try {
      new SimpleTask<Void>(){
        @Override protected Void onExecute(        Context context,        Bundle args) throws Throwable {
          long[] ids=args.getLongArray("ids");
          for (        long id : ids)         lockMessage(id);
          return null;
        }
        @Override protected void onException(        Bundle args,        Throwable ex){
          Log.unexpectedError(getParentFragmentManager(),ex);
        }
      }
      .execute(this,args,"messages:lock");
    } catch (UnsupportedOperationException | ClassCastException | SecurityException | IllegalArgumentException e) {
      Log.unexpectedError(getParentFragmentManager(), e);
    }
  }
}
